package de.corporate.lc.user.service;
import de.corporate.lc.user.domain.*; import de.corporate.lc.user.repository.AppUserRepository; import org.slf4j.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component;
@Component public class InitialAdminInitializer implements ApplicationRunner {private static final Logger log=LoggerFactory.getLogger(InitialAdminInitializer.class);private final AppUserRepository repo;private final PasswordEncoder encoder;@Value("${app.initial-admin.username:admin}")private String username;@Value("${app.initial-admin.password:}")private String configuredPassword;@Value("${app.initial-admin.reset-password:false}")private boolean resetPassword;public InitialAdminInitializer(AppUserRepository r,PasswordEncoder e){repo=r;encoder=e;}@Override public void run(ApplicationArguments args){if(repo.count()>0){if(resetPassword){if(configuredPassword==null||configuredPassword.isBlank())throw new IllegalStateException("ADMIN_PASSWORD must be set when ADMIN_RESET_PASSWORD is enabled");AppUser user=repo.findByUsernameIgnoreCase(username).orElseThrow(()->new IllegalStateException("Configured administrator not found"));user.setPasswordHash(encoder.encode(configuredPassword));user.setActive(true);repo.save(user);log.info("Password for administrator '{}' was reset",user.getUsername());}return;}if(configuredPassword==null||configuredPassword.isBlank())throw new IllegalStateException("ADMIN_PASSWORD must be set before the first start");AppUser user=new AppUser();user.setUsername(username.trim().toLowerCase());user.setDisplayName("Administrator");user.setRole(UserRole.ADMIN);user.setActive(true);user.setPasswordHash(encoder.encode(configuredPassword));repo.save(user);log.info("Initial administrator '{}' created",user.getUsername());}}
